18	    option (google.api.http) = {get: "/api/v1/auth/me"};
19	  }
20	
21	  // SignIn authenticates a user with credentials and returns tokens.
22	  // On success, returns an access token and sets a refresh token cookie.
23	  // Supports password-based and SSO authentication methods.
24	  rpc SignIn(SignInRequest) returns (SignInResponse) {
25	    option (google.api.http) = {
26	      post: "/api/v1/auth/signin"
27	      body: "*"
28	    };
29	  }
30	
31	  // SignOut terminates the user's authentication.
32	  // Revokes the refresh token and clears the authentication cookie.
33	  rpc SignOut(SignOutRequest) returns (google.protobuf.Empty) {
34	    option (google.api.http) = {post: "/api/v1/auth/signout"};
35	  }
